import{_ as o,l as i,o as e,c as l,v as n,p as s,x as r,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"契约条款","description":"","frontmatter":{"title":"契约条款","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/covenants.md","filePath":"econ/covenants.md","lastUpdated":1789023840000}'),p={name:"econ/covenants.md"};function A(h,a,B,m,_,f){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="契约条款" tabindex="-1">契约条款 <a class="header-anchor" href="#契约条款" aria-label="Permalink to &quot;契约条款&quot;">​</a></h1><div class="epigraph"><p>债券契约把资产替代、稀释、股利掏空写成可验证的禁止项；它用状态依存的限制去替代把所有债务都做成短债。</p><footer>—— Smith and Warner, On Financial Contracting: An Analysis of Bond Covenants, Journal of Financial Economics 1979</footer></div><p><a href="/econ/debt-maturity-rollover">上一课</a>用到期日做检查。本课缺口是合同文本：Smith–Warner（1979）把条款分类为投资、融资、股利限制，用来降低代理成本，同时承认条款有灵活性成本。不重写展期危机的扩散模型，不把破产法提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/risk-shifting">风险转移</a>与积压来自优先级。短债用再定价来约束，但流动性代价高。条款用会计门槛（利息覆盖、杠杆上限）、资产出售限制、负向质押、股利限制，在长债内存入检查。缺口是：哪些扭曲可写成可验证条款，哪些只能靠控制权转移（违约）。Tirole：可验证的用契约，不可验证的用权威——与<a href="/econ/control-rights">控制权</a>同一不完全合同分工。</p><p><span class="marginnote">松弛（slack）：企业与门槛的距离。松弛耗尽触发技术性违约，即使清偿力尚在。条款把「违约」从无力偿债提前到比率违规，是故意的早期检查。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Smith–Warner 的清单：限制兼并与资产出售（防资产替代与担保稀释）；限制优先债与抵押（防索赔稀释）；限制股利与回购（防掏空）。收益：债值上升、股权的代理成本下降，事前 \\(V\\) 可以升。成本：正 NPV 的重组、投资、派息被拦下——灵活性像卖掉实物期权。</p><p>松紧与价格：紧条款降低票息，但提高技术性违约与再谈判频率。动态权衡：条款是调整带之外的另一套边界。评级机构把条款包进评级，后课再写。</p>',9)),(e(),s(d,null,{default:r(()=>[c(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20AG%5B%22%E8%B5%84%E4%BA%A7%E6%9B%BF%E4%BB%A3%20%2F%20%E7%A8%80%E9%87%8A%20%2F%20%E6%8E%8F%E7%A9%BA%22%5D%20--%3E%20COV%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20COV%20--%3E%20GAIN%5B%22%E5%80%BA%E5%80%BC%E4%B8%8A%E5%8D%87%2C%20%E4%BA%8B%E5%89%8D%20V%22%5D%0A%20%20COV%20--%3E%20FLEX%5B%22%E7%81%B5%E6%B4%BB%E6%80%A7%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SHORT%5B%22%E7%9F%AD%E5%80%BA%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20ALT%5B%22%E6%9B%BF%E4%BB%A3%E6%88%96%E4%BA%92%E8%A1%A5%22%5D%0A%20%20COV%20--%3E%20CHK%5B%22%E6%AF%94%E7%8E%87%E9%97%A8%E6%A7%9B%20%3D%20%E6%97%A9%E6%9C%9F%E8%BF%9D%E7%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>资本预算：项目可能撞上已有条款（capex 限制、杠杆测试）。NPV 要含再谈判或豁免的成本，不是只算经营 FCFF。这是 APV 的契约副作用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把不可定价的道德风险改写成可验证的约束。条款越完整，越接近把企业变成「按合同经营」——灵活性损失正是实物期权价值。再谈判使条款不是硬约束：违约后可以豁免，于是条款的纪律取决于债权人协调（后课）与是否有银行牵头。</p><p>与 Jensen 债务纪律：还本是硬现金吐出；条款是行为限制。成熟 FCF 企业可能同时要两者；成长企业紧条款会加重积压。样本仍要匹配。</p><h3 id="条款不是免费的状态依存债" tabindex="-1">条款不是免费的状态依存债 <a class="header-anchor" href="#条款不是免费的状态依存债" aria-label="Permalink to &quot;条款不是免费的状态依存债&quot;">​</a></h3><p>把所有或有都写成条款，合同会不可执行或过度触发。最优是不完备：留下违约后的破产/重整来处理残差。这正是下一单元治理与第 11 章的接口，本课只在合同设计上点名。</p><p><span class="marginnote">Brealey–Myers：条款保护债权人，最终也保护股东——因为事前降低债务成本。事后股东会感觉被条款绑住，这是同一合同的两面，不是矛盾。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成信托契约的法律注释。对象是代理成本与灵活性。下一课银行债对公开债：谁持有条款、谁能监督与豁免，决定条款的实际硬度。</p><p>后课默认：条款用可验证限制替代部分短债检查；代价是实物期权。项目 NPV 必须读已有契约。技术性违约 ≠ 经济破产。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条款针对投资、融资、股利三类代理，用可验证门槛做早期检查。</li><li>收益是事前债值；成本是灵活性与再谈判。</li><li>与短债互补或替代；硬度取决于谁监督、能否协调豁免。</li><li>出处：Smith and Warner, <em>JFE</em> 1979；Tirole, <em>Theory of Corporate Finance</em>。</li></ul>',12))])}const C=o(p,[["render",A]]);export{F as __pageData,C as default};
